// fxp_round_ooc: out-of-context wrapper for the fxp_round variants (brief 139b, generated by arith/tools/gen_build.py: do not edit).
// Registers every input and every output of fxp_round_sel, so the paths Vivado times are the core's own, register to register, and the
// ports (which an out-of-context run leaves unplaced) carry no timing. rst is registered once; the core's reset is the synchronous one.
// This is a timing harness: in_ready is registered too, so for an iterative variant (whose in_ready is not constant) the wrapper does not keep the
// handshake; it is functionally exact for the always-ready (pipelined, one-clock) variants, which tb_<function>.sv simulates through it with WRAP = 1.
module fxp_round_ooc #(
    parameter int VARIANT = 0,
    parameter int W_IN = 32,
    parameter int S = 12,
    parameter int W_OUT = 18,
    parameter int MODE = 2,
    parameter int SAT = 1
) (
    input  logic                 clk,
    input  logic                 rst,
    input  logic                 in_valid,
    output logic                 in_ready,
    input  logic [W_IN-1:0]  in_data,
    output logic                 out_valid,
    output logic [W_OUT-1:0] out_data
);
    logic                 rst_q, v_q, ready_c, ov_c;
    logic [W_IN-1:0]  d_q;
    logic [W_OUT-1:0] od_c;

    always_ff @(posedge clk) begin
        rst_q <= rst;
        v_q   <= in_valid;
        d_q   <= in_data;
    end

    fxp_round_sel #(.VARIANT(VARIANT), .W_IN(W_IN), .S(S), .W_OUT(W_OUT), .MODE(MODE), .SAT(SAT)) u_core (
        .clk, .rst(rst_q), .in_valid(v_q), .in_ready(ready_c), .in_data(d_q), .out_valid(ov_c), .out_data(od_c));

    always_ff @(posedge clk) begin
        in_ready  <= ready_c;
        out_valid <= ov_c;
        out_data  <= od_c;
    end
endmodule
